head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.LastJob = "조회";
// 화면 리사이징

// 번역지원 화면 서식 추가 팝업
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gRdoMktId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_jongmok_OnLoadCompleted
 * @description dts_jongmok 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            panel_page.show("");
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        } else {
            panel_page.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.dts_jongmok_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.img_search_onclick" });
    }
};

/**
 * @method
 * @name img_add_onclick
 * @description 「추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_add_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.img_add_onclick" });
    }
};

/**
 * @method
 * @name grd_jongmok_oncheckclick
 * @description grd_jongmok oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_jongmok_oncheckclick = function(col, colid, bCheck) {
    // alert('grd_jongmok.OnCheckClick('+col+','+ colid+','+ bCheck+')');

};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 실패");
        await $c.win.alert(trs_Save);
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 완료되었습니다.");
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_com_srch_onclick = async function() {
    try {
        // *** 셋팅할 필드명 정의를 아래처럼 해야함.
        // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
        scwin.gRdoMktId = rdo_MKT_ID.getValue();
        let url = "./ULDSTF19000_FORM_POP.gfm";
        const winTitle = "공시제목선택 ";
        await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 695, 575, "window");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name img_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_delete_onclick = async function() {
    try {
        cCnt = 0;
        for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
            if (dts_jongmok.getCellData(i, "CHK_FLAG") === 1) {
                cCnt++;
                break;
            }
        }
        if (cCnt === 0) {
            await $c.win.alert("삭제할 서식을 선택해주세요.");
            return;
        } else {
            if (window.confirm("정말 삭제하시겠습니까?")) {
                let tmpInt = 1;
                dts_Save.setBroadcast(false);
                for (let i = 1; i <= dts_jongmok.getRowCount(); i++) {
                    if (dts_jongmok.getCellData(i, "CHK_FLAG") === 1) {
                        dts_Save.insertRow();
                        dts_Save.setCellData(tmpInt, "FORM_CD", dts_jongmok.getCellData(i, "FORM_CD"));
                        dts_Save.setCellData(tmpInt, "FORM_VER", dts_jongmok.getCellData(i, "FORM_VER"));
                        tmpInt++;
                    }
                }
                dts_Save.setBroadcast(true, true);
                await scwin.delete();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.img_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF19000_FORM.xml", SCREN_PROCS_TP_CD_02);
        $c.data.downloadGridViewOffice(grd_jongmok, "영문번역대상서식 목록", "영문번역대상서식 목록" + ".xlsx", "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_FORM.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Save.insertRow();
    await scwin.search();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&LD_MKT_TP=" + rdo_MKT_ID.getValue(); // 시장구분
    // url += "&SCREN_ID=" + vScrenID;
    // url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_FormCd.getValue().length !== 5) {
        await $c.win.alert("서식 코드 5자리를 입력해주세요");
        img_com_srch.focus();
        return;
    }
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        if (dts_jongmok.getCellData(i, "FORM_CD") === txb_FormCd.getValue()) {
            await $c.win.alert("이미 등록된 서식입니다.");
            return;
        }
    }
    dts_Save.setCellData(1, "FORM_CD", txb_FormCd.getValue());
    dts_Save.setCellData(1, "FORM_VER", txb_FormVer.getValue());
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    dts_Save.setCellData(1, "LD_MKT_TP_CD", rdo_MKT_ID.getValue());
    scwin.LastJob = "추가";
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/DsclSearchAll.do",
        ref : "dts_Save",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    dts_Save.setCellData(1, "LD_MKT_TP_CD", rdo_MKT_ID.getValue());
    scwin.LastJob = "삭제";
    // dts_Save.UserStatus(1) = TB_JOB_DELETE;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/DsclSearchAll.do",
        ref : "dts_Save",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        rdo_MKT_ID.setValue(js_market);
        rdo_MKT_ID.setDisabled(true);
    } else {
        scwin.gRdoMktId = $c.frame.path("../").scwin.gRdoMktId;
        rdo_MKT_ID.setValue(scwin.gRdoMktId);
        rdo_MKT_ID.setDisabled(false);
    }
    await scwin.setHeader();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    // gComAbbrv = dts_jongmok.NameString(eval(obj),"COM_ABBRV");
    gIsurCd = dts_jongmok.getCellData(Number(obj), "ISUR_CD");
};
